    'firstkings': 'books.firstKings',
    '1kings': 'books.firstKings',
    'secondkings': 'books.secondKings',
    '2kings': 'books.secondKings',
    'firstchronicles': 'books.firstChronicles',
    '1chronicles': 'books.firstChronicles',
    'secondchronicles': 'books.secondChronicles',
    '2chronicles': 'books.secondChronicles',
    'ezra': 'books.ezra',
    'nehemiah': 'books.nehemiah',
    'esther': 'books.esther',
    'job': 'books.job',
    'psalms': 'books.psalms',
    'proverbs': 'books.proverbs',
    'ecclesiastes': 'books.ecclesiastes',
    'solomon': 'books.solomon',
    'isaiah': 'books.isaiah',
    'jeremiah': 'books.jeremiah',
    'lamentations': 'books.lamentations',
    'ezekiel': 'books.ezekiel',
    'daniel': 'books.daniel',
    'hosea': 'books.hosea',
    'joel': 'books.joel',
    'amos': 'books.amos',
    'obadiah': 'books.obadiah',
    'jonah': 'books.jonah',
    'micah': 'books.micah',
    'nahum': 'books.nahum',
    'habakkuk': 'books.habakkuk',
    'zephaniah': 'books.zephaniah',
    'haggai': 'books.haggai',
    'zechariah': 'books.zechariah',
    'malachi': 'books.malachi',
    // New Testament
    'matthew': 'books.matthew',
