/**
 * Check if a string is a Chinese book name and return the English equivalent
 * Also handles partial matches (e.g., "创世记 1" should match "创世记")
 */
export const detectChineseBookName = (searchTerm: string): { chineseName: string; englishName: string; remaining: string } | null => {
  if (!searchTerm) return null;
  
  // Map Chinese book names to English API format
  // Sort by length (longest first) to match longer names first (e.g., "撒母耳记上" before "撒母耳")
  const chineseToEnglishMap: Record<string, string> = {
    // Old Testament - sorted by length (longest first for proper matching)
    '撒母耳记下': 'secondSamuel',
    '撒母耳记上': 'firstSamuel',
    '列王纪下': 'secondKings',
    '列王纪上': 'firstKings',
    '历代志下': 'secondChronicles',
    '历代志上': 'firstChronicles',
    '耶利米哀歌': 'lamentations',
    '约书亚记': 'joshua',
    '出埃及记': 'exodus',
    '利未记': 'leviticus',
    '民数记': 'numbers',
    '申命记': 'deuteronomy',
    '士师记': 'judges',
    '路得记': 'ruth',
    '以斯拉记': 'ezra',
    '尼希米记': 'nehemiah',
    '以斯帖记': 'esther',
    '约伯记': 'job',
    '传道书': 'ecclesiastes',
    '以赛亚书': 'isaiah',
    '耶利米书': 'jeremiah',
    '以西结书': 'ezekiel',
    '但以理书': 'daniel',
    '何西阿书': 'hosea',
    '约珥书': 'joel',
    '阿摩司书': 'amos',
    '俄巴底亚书': 'obadiah',
    '约拿书': 'jonah',
    '弥迦书': 'micah',
    '那鸿书': 'nahum',
    '哈巴谷书': 'habakkuk',
    '西番雅书': 'zephaniah',
    '哈该书': 'haggai',
    '撒迦利亚书': 'zechariah',
    '玛拉基书': 'malachi',
    '创世记': 'genesis',
    '诗篇': 'psalms',
    '箴言': 'proverbs',
    '雅歌': 'solomon',
    // New Testament - sorted by length
    '帖撒罗尼迦后书': 'secondThessalonians',
    '帖撒罗尼迦前书': 'firstThessalonians',
    '提摩太后书': 'secondTimothy',
    '提摩太前书': 'firstTimothy',
    '哥林多后书': 'secondCorinthians',
    '哥林多前书': 'firstCorinthians',
    '约翰三书': 'thirdJohn',
    '约翰二书': 'secondJohn',
    '约翰一书': 'firstJohn',
    '彼得后书': 'secondPeter',
    '彼得前书': 'firstPeter',
    '马太福音': 'matthew',
    '马可福音': 'mark',
    '路加福音': 'luke',
    '约翰福音': 'john',
    '使徒行传': 'acts',
    '加拉太书': 'galatians',
    '以弗所书': 'ephesians',
    '腓立比书': 'philippians',
    '歌罗西书': 'colossians',
    '提多书': 'titus',
    '腓利门书': 'philemon',
    '希伯来书': 'hebrews',
    '雅各书': 'james',
    '犹大书': 'jude',
    '罗马书': 'romans',
    '启示录': 'revelation',
  };
  
  // Sort by key length (longest first) to match longer names before shorter ones
  const sortedEntries = Object.entries(chineseToEnglishMap).sort((a, b) => b[0].length - a[0].length);
  
  const trimmedTerm = searchTerm.trim();
  
  // First, try exact match or prefix match (for cases like "创世记 1:1" or "创世记 1")
  for (const [chineseName, englishName] of sortedEntries) {
    if (trimmedTerm === chineseName || trimmedTerm.startsWith(chineseName)) {
      // Extract the part after the book name (chapter:verse)
      const remaining = trimmedTerm.substring(chineseName.length).trim();
      return { chineseName, englishName, remaining };
    }
  }
  
  // If no exact/prefix match, try partial matching (e.g., "利未" matches "利未记")
  // This allows searching with partial book names
  for (const [chineseName, englishName] of sortedEntries) {
    // Check if search term is contained in the book name (e.g., "利未" in "利未记")
    // Only match if the search term is at the start of the book name
    if (chineseName.startsWith(trimmedTerm) && trimmedTerm.length >= 1) {
      // For partial matches, assume they want the full book
      // No chapter:verse specified
      return { chineseName, englishName, remaining: '' };
    }
  }
  
  return null;
};


