import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import Cookies from 'js-cookie';
import enTranslations from './locales/en.json';
import zhTranslations from './locales/zh-hans.json';

// Get translation from localStorage/cookies and map to locale
const getTranslation = (): string => {
  const translation = Cookies.get('translation') || localStorage.getItem('translation') || 'kjv';
  // Map translation to locale: kjv -> en, cuv -> zh-hans
  return translation === 'cuv' ? 'zh-hans' : 'en';
};

i18n
  .use(initReactI18next)
  .init({
    resources: {
      en: {
        translation: enTranslations,
      },
      'zh-hans': {
        translation: zhTranslations,
      },
    },
    lng: getTranslation(),
    fallbackLng: 'en',
    interpolation: {
      escapeValue: false, // React already escapes values
    },
    react: {
      useSuspense: false, // Disable suspense to prevent issues
    },
    // Ensure language changes trigger updates
    debug: process.env.NODE_ENV === 'development',
  });

// Watch for changes in translation and update locale
export const updateLocaleFromTranslation = () => {
  const translation = Cookies.get('translation') || localStorage.getItem('translation') || 'kjv';
  const locale = translation === 'cuv' ? 'zh-hans' : 'en';
  if (i18n.language !== locale) {
    i18n.changeLanguage(locale);
  }
};

export default i18n;
