/**
 * Email validation utilities
 */

/**
 * Checks if an email domain is blocked
 * @param email - The email address to check
 * @returns true if the email domain is blocked, false otherwise
 */
export const isEmailDomainBlocked = (email: string): boolean => {
  if (!email || typeof email !== 'string') {
    return false;
  }

  // Extract domain from email
  const domain = email.split('@')[1];
  if (!domain) {
    return false;
  }

  // List of blocked domains (case-insensitive)
  const blockedDomains = [
    '.ru',           // Russia
    '.su',           // Soviet Union (legacy)
    '.рф',           // Russia (Cyrillic)
  ];

  // Check if domain ends with any blocked domain
  const lowerDomain = domain.toLowerCase();
  return blockedDomains.some(blockedDomain => 
    lowerDomain.endsWith(blockedDomain.toLowerCase())
  );
};

/**
 * Validates email format and checks for blocked domains
 * @param email - The email address to validate
 * @returns object with isValid boolean and error message if invalid
 */
export const validateEmail = (email: string): { isValid: boolean; error?: string } => {
  if (!email || typeof email !== 'string') {
    return { isValid: false, error: 'Email is required' };
  }

  // Basic email format validation
  const emailRegex = /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
  
  if (!emailRegex.test(email.toLowerCase())) {
    return { isValid: false, error: 'Please enter a valid email address' };
  }

  // Check for blocked domains
  if (isEmailDomainBlocked(email)) {
    return { isValid: false, error: "Don't worry you can still read the bible for free without an email. If you'd still like to sign up please email us" };
  }

  return { isValid: true };
};

/**
 * Gets a user-friendly error message for blocked email domains
 * @param email - The email address that was blocked
 * @returns A user-friendly error message
 */
export const getBlockedDomainMessage = (email: string): string => {
  return "Don't worry you can still read the bible for free without an email. If you'd still like to sign up please email us";
};
